using System;using System.IO;
internal static class LegacyFiles28 {
 internal static void Retire(string target,string jobDir){target=Path.GetFullPath(target).TrimEnd(Path.DirectorySeparatorChar);foreach(string name in new[]{"编辑修复说明.txt","触控修复说明.txt","多效果使用说明.txt","风格说明.txt","联动使用说明.txt","桌面使用说明.txt","手机与电脑使用说明.txt","枭熊联动说明.txt","v0.14更新与互通说明.txt","v0.16更新与使用说明.txt","v0.17更新与使用说明.txt","v0.19更新与使用说明.txt","v0.20更新与使用说明.txt","v0.21更新与使用说明.txt","v0.22更新与使用说明.txt","v0.23更新与使用说明.txt","v0.24更新与使用说明.txt","v0.25更新与使用说明.txt","v0.26更新与使用说明.txt","v0.27更新与使用说明.txt","v0.27.1更新与使用说明.txt","v0.27.2更新与使用说明.txt"}){try{string file=Path.Combine(target,name);CheckParents(target,file);if(!File.Exists(file))continue;string old=Path.Combine(jobDir,"retired-guides28",name);Directory.CreateDirectory(Path.GetDirectoryName(old));File.Copy(file,old,true);File.Delete(file);}catch{}}}
 internal static void RejectLink(string path){try{if((File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new Exception("安装路径包含链接，无法安全替换");}catch(FileNotFoundException){}catch(DirectoryNotFoundException){}}
 internal static void CheckParents(string root,string dest){RejectLink(dest);var current=new DirectoryInfo(Path.GetDirectoryName(dest));while(current!=null&&current.FullName.Length>=root.Length){RejectLink(current.FullName);if(string.Equals(current.FullName,root,StringComparison.OrdinalIgnoreCase))return;current=current.Parent;}throw new Exception("安装路径越界");}
}
